669		resp, err := client.Get(ctx, v4ServicePath+"?"+q.Encode())
670		if err != nil {
671			return nil, fmt.Errorf("calling search service: %w", err)
672		}
673		defer resp.Body.Close()
674	
675		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
676		if err != nil {
677			return nil, fmt.Errorf("reading response: %w", err)
678		}
679		if resp.StatusCode == http.StatusNotFound {
680			// Two distinct 404s share this status. A JSON error body is
681			// query-serve answering through the gateway: the route exists but the
682			// repo filter matched nothing the caller may search (not indexed, or
683			// the owner org isn't flag-enabled — entire-search fails closed,
684			// existence not disclosed). A plain "404 page not found" is the
685			// gateway itself: no semantic-search route, query-serve not deployed
686			// in this cell. Deployed cells answer unfiltered searches of unknown
